#!/usr/bin/env bash
# Ravana boot animation (Plymouth two-step): crown with a breathing glow and a
# light sweep, RAVANA wordmark. Frames live in system_files/usr/share/plymouth/themes/ravana
# (generated by tools/gen-boot-assets.py). 90-initramfs.sh rebuilds the initramfs.
set -euxo pipefail
echo "Base Plymouth theme: $(plymouth-set-default-theme 2>/dev/null || echo unknown)"
THEME=/usr/share/plymouth/themes/ravana
SPINNER=/usr/share/plymouth/themes/spinner
test -f "$THEME/ravana.plymouth"
test -f "$THEME/throbber-0001.png"

# Password prompt / keyboard indicator images (disk encryption) from spinner
if [ -d "$SPINNER" ]; then
    for f in "$SPINNER"/*.png; do
        case "$(basename "$f")" in
            throbber-*|animation-*|watermark.png|background*.png) ;;
            *) cp -n "$f" "$THEME/" ;;
        esac
    done
fi
ls "$THEME" | grep -v throbber-
plymouth-set-default-theme ravana
test "$(plymouth-set-default-theme)" = ravana
